import React, { useState } from 'react';

function JobList({ jobs, onDeleteJob, onEditJob }) {
  const [editingJob, setEditingJob] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editCompany, setEditCompany] = useState('');
  const [editSalary, setEditSalary] = useState('');
  const [editSector, setEditSector] = useState('');

  const handleEdit = (job) => {
    setEditingJob(job);
    setEditTitle(job.title);
    setEditCompany(job.company);
    setEditSalary(job.salary);
    setEditSector(job.sector);
    setShowModal(true);
  };

  const handleSaveEdit = () => {
    const updatedJob = {
      ...editingJob,
      title: editTitle,
      company: editCompany,
      salary: parseFloat(editSalary),
      sector: editSector,
    };
    onEditJob(updatedJob);
    setShowModal(false);
    setEditingJob(null);
  };

  const handleCancelEdit = () => {
    setShowModal(false);
    setEditingJob(null);
  };

  return (
    <div>
      <h2>Job List</h2>
      {jobs.length === 0 ? (
        <p>No jobs available. Please add a job using the form above.</p>
      ) : (
        <ul style={{ padding: 0 }}>
          {jobs.map((job) => (
            <li
              key={job.id}
              style={{
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                background: '#fff',
                marginBottom: '10px',
                padding: '15px',
                borderRadius: '6px',
                boxShadow: '0 1px 4px rgba(0,0,0,0.1)',
                fontSize: '18px',
                color: '#2c3e50',
              }}
            >
              <span>
                <strong>{job.title}</strong> at {job.company} - ${job.salary.toLocaleString()} ({job.sector})
              </span>
              <div>
                <button
                  onClick={() => handleEdit(job)}
                  style={{
                    backgroundColor: '#007bff',
                    border: 'none',
                    color: 'white',
                    padding: '8px 12px',
                    borderRadius: '4px',
                    cursor: 'pointer',
                    fontSize: '14px',
                    marginRight: '10px',
                    transition: 'background-color 0.3s ease',
                  }}
                  onMouseOver={e => e.currentTarget.style.backgroundColor = '#0056b3'}
                  onMouseOut={e => e.currentTarget.style.backgroundColor = '#007bff'}
                  aria-label={`Edit job ${job.title}`}
                >
                  Edit
                </button>
                <button
                  onClick={() => onDeleteJob(job.id)}
                  style={{
                    backgroundColor: '#e74c3c',
                    border: 'none',
                    color: 'white',
                    padding: '8px 12px',
                    borderRadius: '4px',
                    cursor: 'pointer',
                    fontSize: '14px',
                    transition: 'background-color 0.3s ease',
                  }}
                  onMouseOver={e => e.currentTarget.style.backgroundColor = '#c0392b'}
                  onMouseOut={e => e.currentTarget.style.backgroundColor = '#e74c3c'}
                  aria-label={`Delete job ${job.title}`}
                >
                  Delete
                </button>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default JobList;
